const CACHE='lang-nghe-shell-v29-static-1';
const ASSETS=['./','./index.html','./style.css','./caption-layout.css','./listening-layout.css','./dock.css','./youtube-controls.js?v=29','./caption-picker.js?v=29','./youtube.js?v=29','./shared-library.js?v=29','./account.js?v=29','./app.js?v=29','./practice.js?v=12','./core.js?v=8','./word-timing.js?v=8','./ipa.js?v=8','./ipa-data.js?v=8','./IPA-LICENSE.txt','./manifest.json','./icon.svg'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('lang-nghe-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(new URL(e.request.url).pathname.startsWith('/api/'))return;if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
